    20→
    21→export class VM {
    22→  private stack: Value[] = [];
    23→  private globals = new Map<string, Value>();
    24→  private frames: Frame[] = [];
    25→  private tryStack: TryHandler[] = [];
    26→  private ip = 0;
    27→  private output: string[] = [];
    28→  private builtinFns: Record<string, BuiltinFn>;
    29→  // Phase 8: try/catch error handling
    30→  private lastError: Value | null = null;
    31→  private inTryCall = false;
    32→  // Phase 3.7: Safety guard & iteration tracking
    33→  // Phase 3.9: Jump Table & Offset Optimization
    34→  private jumpTable: JumpTable;
    35→  private offsetCalc: OffsetCalculator = new OffsetCalculator();
    36→  // Phase 5.9: Dynamic Memory Allocator
    37→  private memoryAllocator: MemoryAllocator = new MemoryAllocator();
    38→
    39→  private traceMode = false;
    40→  private traceLogs: string[] = [];
    41→  private loopStack: LoopContext[] = [];  // Track loop start positions + iteration counts
    42→  private loopDepth = 0;                   // Track nesting depth
    43→  private readonly MAX_SAFE_ITERATIONS = 1_000_000;  // Safety guard limit
    44→
    45→  constructor(private chunk: Chunk, initialGlobals?: Map<string, Value>) {
    46→    this.builtinFns = getBuiltins();
    47→    this.jumpTable = new JumpTable(this.loopStack);
    48→
    49→    // Register builtins
    50→    for (const name of Object.keys(this.builtinFns)) {
    51→      this.globals.set(name, { tag: "builtin", name });
    52→    }
    53→    // Restore persisted globals (e.g. from REPL)
    54→    if (initialGlobals) {
    55→      for (const [k, v] of initialGlobals) {
    56→        if (!this.globals.has(k)) this.globals.set(k, v);
    57→      }
    58→    }
    59→  }
    60→
    61→  getGlobals(): Map<string, Value> { return new Map(this.globals); }
    62→
    63→  run(): { output: string[]; result: Value } {
    64→    while (this.ip < this.chunk.code.length) {
    65→      const op = this.chunk.code[this.ip++];
    66→      if (op === Op.Halt) {
    67→        return { output: this.output, result: this.stack.length > 0 ? this.peek() : { tag: "null" } };
    68→      }
    69→      try {
    70→        this.execOp(op);
    71→      } catch (e) {
    72→        // If error was caught by a try handler
    73→        if (e instanceof Error && e.message.startsWith("__FREELANG_ERROR_CAUGHT__")) {
    74→          // Continue from the new IP (which should point to catch handler or finally)
    75→          continue;
    76→        }
    77→        // Re-throw unhandled errors
    78→        throw e;
    79→      }
    80→    }
    81→    return { output: this.output, result: { tag: "null" } };
    82→  }
    83→
    84→  // Public API for builtins
    85→  getGlobal(name: string): Value | undefined { return this.globals.get(name); }
    86→  setGlobal(name: string, val: Value) { this.globals.set(name, val); }
    87→  getOutput(): string[] { return this.output; }
    88→  addOutput(s: string) { this.output.push(s); }
    89→  getLastError(): Value | null { return this.lastError; }
    90→  clearLastError() { this.lastError = null; }
    91→
    92→  // Phase 5.9: Memory Allocator API for builtins
    93→  getAllocator() { return this.memoryAllocator; }
    94→
    95→  // Trace mode for PC debugging
    96→  enableTrace() { this.traceMode = true; this.traceLogs = []; }
    97→  getTraceLogs(): string[] { return this.traceLogs; }
    98→
    99→  /** Call a FreeLang fn or builtin Value from within a builtin (HOFs). */
   100→  callValue(callee: Value, args: Value[]): Value {
   101→    if (callee.tag === "builtin") {
   102→      return this.builtinFns[callee.name](args, this);
   103→    }
   104→    if (callee.tag === "fn") {
   105→      const savedIp = this.ip;
   106→      const targetFrameDepth = this.frames.length;
   107→
   108→      // Mimic Call opcode: push callee + args, push frame
   109→      this.stack.push(callee);
   110→      for (const a of args) this.stack.push(a);
   111→      this.frames.push({
   112→        retAddr: savedIp,
   113→        baseSlot: this.stack.length - args.length,
   114→        fn: callee.name,
   115→        upvalues: callee.freeVars,
   116→      });
   117→      this.ip = callee.addr;
   118→
   119→      // Execute until our frame is popped by Return
   120→      try {
   121→        while (this.frames.length > targetFrameDepth) {
   122→          const op = this.chunk.code[this.ip++];
   123→          this.execOp(op);
   124→        }
   125→      } catch (e) {
   126→        // Re-throw sentinel errors so try_call can catch them
   127→        if (e instanceof Error && e.message === "__FREELANG_ERROR_CAUGHT__") {
   128→          throw e;
   129→        }
   130→        // Re-throw other errors
   131→        throw e;
   132→      }
   133→      // Return handler pushed the result onto the stack and restored ip
   134→      return this.stack.pop()!;
   135→    }
   136→    throw new Error(`Cannot call ${callee.tag}`);
   137→  }
   138→
   139→  /** Safe call for try_call builtin - captures errors as Value objects */
   140→  trySafeCall(callee: Value, args: Value[]): { ok: boolean; value?: Value; error?: Value } {
   141→    this.clearLastError();
   142→    this.inTryCall = true;
   143→
   144→    try {
   145→      if (callee.tag === "builtin") {
   146→        const retVal = this.builtinFns[callee.name](args, this);
   147→        return { ok: true, value: retVal };
   148→      }
   149→      if (callee.tag === "fn") {
   150→        const retVal = this.callValue(callee, args);
   151→        return { ok: true, value: retVal };
   152→      }
   153→      return { ok: false, error: { tag: "str", val: `Cannot call ${callee.tag}` } };
   154→    } catch (e) {
   155→      // Check if a FreeLang error occurred
   156→      if (e instanceof Error && e.message.startsWith("__FREELANG_ERROR_CAUGHT__")) {
   157→        // Return the last error that was caught
   158→        return { ok: false, error: this.lastError || { tag: "str", val: "Unknown error" } };
   159→      }
   160→      // Otherwise return string error
   161→      return { ok: false, error: { tag: "str", val: String(e) } };
   162→    } finally {
   163→      this.inTryCall = false;
   164→    }
   165→  }
   166→
   167→  stringify(v: Value): string {
   168→    switch (v.tag) {
   169→      case "num": return String(v.val);
   170→      case "str": return v.val;
   171→      case "bool": return String(v.val);
   172→      case "null": return "null";
   173→      case "array": return "[" + v.val.map(e => this.stringify(e)).join(", ") + "]";
   174→      case "object": {
   175→        const entries = Array.from(v.val.entries()).map(([k, v2]) => `${k}: ${this.stringify(v2)}`);
