   337→      case Op.StoreGlobal: {
   338→        const name = this.chunk.constants[this.chunk.code[this.ip++]] as { tag: "str"; val: string };
   339→        this.globals.set(name.val, this.pop());
   340→        break;
   341→      }
   342→
   343→      // Functions
   344→      case Op.Call: {
