        advance();
      }
      returnType = returnTokens.join("");
    }

    expect(T.LBrace);
    const body = parseBody();
    expect(T.RBrace);
    return { kind: "fn", name, params, returnType, body };
  }

  function parseReturn(): Stmt {
    advance(); // return
    let value: Expr | null = null;
    if (!at(T.Semicolon) && !at(T.RBrace) && !at(T.EOF)) value = parseExpr();
    match(T.Semicolon);
    return { kind: "return", value };
  }

  function parseIf(): Stmt {
    advance(); // if

    // Check for if let pattern
    if (at(T.Let)) {
      return parseIfLet();
    }

    const cond = parseExpr();
    expect(T.LBrace);
    const then = parseBody();
    expect(T.RBrace);
    let else_: Stmt[] | null = null;
    if (match(T.Else)) {
      if (at(T.If)) {
        else_ = [parseIf()];
      } else {
        expect(T.LBrace);
        else_ = parseBody();
        expect(T.RBrace);
      }
    }
    return { kind: "if", cond, then, else: else_ };
  }

  function parseIfLet(): Stmt {
    advance(); // let
    const pattern = parseOr(); // Use parseOr to avoid consuming the = operator
    expect(T.Assign);
    const value = parseOr(); // Use parseOr for consistency
    expect(T.LBrace);
    const body = parseBody();
    expect(T.RBrace);

    let else_: Stmt[] | undefined;
    if (match(T.Else)) {
      if (at(T.LBrace)) {
        expect(T.LBrace);
        else_ = parseBody();
        expect(T.RBrace);
      } else if (at(T.If)) {
        // else if pattern
        else_ = [parseIf()];
      }
