            expect(T.RBrace);
            return { kind: "fn", name: null, params: [t.value], body };
          }
          const expr = parseAssign();
          return { kind: "fn", name: null, params: [t.value], body: [{ kind: "return", value: expr }] };
        }
        return { kind: "ident", name: t.value };
      }
      case T.LParen: {
