        let isArrow = true;
        const params: string[] = [];
        const tryPos = pos;
        while (!at(T.RParen) && !at(T.EOF)) {
          if (!at(T.Ident)) { isArrow = false; break; }
          params.push(advance().value);
          if (!at(T.RParen)) {
            if (!match(T.Comma)) { isArrow = false; break; }
          }
